import{_ as e,o as t,c as a,aw as r}from"./chunks/framework.DLufY-ao.js";const d=JSON.parse('{"title":"Создание собственных хуков","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react-hooks/custom-hooks/info.md","filePath":"wiki/dev-commit/framework-react/react-hooks/custom-hooks/info.md"}'),i={name:"wiki/dev-commit/framework-react/react-hooks/custom-hooks/info.md"};function s(c,o,l,m,n,_){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="создание-собственных-хуков" tabindex="-1">Создание собственных хуков <a class="header-anchor" href="#создание-собственных-хуков" aria-label="Permalink to &quot;Создание собственных хуков&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://usehooks.com/" target="_blank" rel="noreferrer">https://usehooks.com/</a></p></div><ul><li>Создание пользовательских хуков позволяет вам перенести логику компонентов в функции, которые можно повторно использовать</li><li>Когда необходимо повторно использовать одинаковую логику состояния в нескольких компонентах. С помощью пользовательских хуков эта задача решается без добавления ненужных компонентов в ваше дерево</li><li>Пользовательские хуки - это в большей степени соглашение, чем дополнение. Если имя функции начинается с ”use” и она вызывает другие хуки, мы расцениваем это как пользовательский хук</li><li>Использование: работа с формами, анимация, декларативные подписки, таймеры и т.д.</li></ul><hr><ul><li>Хуки - это способ использовать повторно логику состояния, а не само состояние. Более того, каждое обращение к хуку обеспечивает совершенно изолированное состояние. Можно использовать один и тот же хук несколько раз в одном компоненте</li></ul>',5)])])}const f=e(i,[["render",s]]);export{d as __pageData,f as default};
